const searchAdminSpots = `-- name: SearchAdminSpots :many
SELECT s.id, s.name, s.kind, s.city, s.country, s.status, s.status_reason,
       s.curated, s.last_verified_at, s.updated_at,
       ST_Y(s.geom::geometry)::float8 AS lat,
       ST_X(s.geom::geometry)::float8 AS lon,
       p.slug AS pack_slug, p.name AS pack_name
FROM t_spots s
JOIN t_city_packs p ON p.id = s.city_pack_id
WHERE ($1::uuid IS NULL OR s.id = $1)
  AND ($2::text IS NULL OR s.name ILIKE $2)
  AND ($3::text IS NULL OR s.status = $3)
  AND ($4::text IS NULL OR p.slug = $4)
ORDER BY s.name NULLS LAST, s.id
LIMIT $5
`

type SearchAdminSpotsParams struct {
	ID       pgtype.UUID `json:"id"`
	Q        pgtype.Text `json:"q"`
	Status   pgtype.Text `json:"status"`
	PackSlug pgtype.Text `json:"pack_slug"`
	RowLimit int32       `json:"row_limit"`
}

type SearchAdminSpotsRow struct {
	ID             uuid.UUID          `json:"id"`
	Name           pgtype.Text        `json:"name"`
	Kind           string             `json:"kind"`
	City           pgtype.Text        `json:"city"`
	Country        string             `json:"country"`
	Status         string             `json:"status"`
	StatusReason   pgtype.Text        `json:"status_reason"`
	Curated        bool               `json:"curated"`
	LastVerifiedAt pgtype.Timestamptz `json:"last_verified_at"`
	UpdatedAt      time.Time          `json:"updated_at"`
	Lat            float64            `json:"lat"`
	Lon            float64            `json:"lon"`
	PackSlug       string             `json:"pack_slug"`
	PackName       string             `json:"pack_name"`
}

// Staff lookup across every status. `q` is an already-escaped ILIKE pattern.
func (q *Queries) SearchAdminSpots(ctx context.Context, arg SearchAdminSpotsParams) ([]SearchAdminSpotsRow, error) {
	rows, err := q.db.Query(ctx, searchAdminSpots,
		arg.ID,
		arg.Q,
		arg.Status,
		arg.PackSlug,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchAdminSpotsRow{}
	for rows.Next() {
		var i SearchAdminSpotsRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Kind,
			&i.City,
			&i.Country,
			&i.Status,
			&i.StatusReason,
			&i.Curated,
			&i.LastVerifiedAt,
			&i.UpdatedAt,
			&i.Lat,
			&i.Lon,
			&i.PackSlug,
			&i.PackName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

